using System.Globalization;
using TownOfHost;
using UnityEngine;
using UnityEngine.UI;
using Obj=UnityEngine.Object;
partial class Program
{
 static IEnumerable<string> AuditLog=>Logger.Infos.Where(s=>s.StartsWith("STATE")||s.StartsWith("PHASE")||s.StartsWith("FRIENDS_RENDER")||s.StartsWith("AUDIT"));
 static void RenderFriendFrame(){Call("BeforeCamera",Camera.main);Call("AfterFriendsCamera",Camera.main);}
 static void FriendsRenderAuditTests()
 {
  Test("IL2CPP-shaped base wrapper makes the legacy CLR sprite predicate false",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;var proxy=x.ui.GetComponentsInChildren<Renderer>(true).Single(r=>r.name=="Blur");Check(proxy is not SpriteRenderer&&proxy.GetComponent<SpriteRenderer>()==blur&&proxy.GetInstanceID()==blur.GetInstanceID());x.view.Dispose();});
  Test("typed Blur lookup suppresses native sprite through a base renderer proxy",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;OpenFriend(x);Pump(x.view);Check(!blur.enabled&&blur.sortingOrder==0&&x.view.Visible);x.view.Dispose();Check(blur.enabled);});
  Test("native instance ID keeps fresh wrappers from accumulating sorting offsets",()=>{var x=FriendFixture();Obj.NativeRendererWrappers=true;OpenFriend(x);for(int i=0;i<100;i++){Pump(x.view,1);Check(x.renderer.sortingOrder==22);}x.view.Dispose();Check(x.renderer.sortingOrder==2);});
  Test("base wrapper for a nested Blur never causes another element to be hidden",()=>{var x=FriendFixture();var menu=new GameObject("Menu");menu.transform.SetParent(x.ui.transform,false);var blur=new GameObject("Blur").AddComponent<SpriteRenderer>();blur.transform.SetParent(menu.transform,false);Obj.NativeRendererWrappers=true;OpenFriend(x);Pump(x.view);Check(blur.enabled);x.view.Dispose();});
  Test("typed native backdrop original disabled state survives close",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui,false);Obj.NativeRendererWrappers=true;OpenFriend(x);Pump(x.view);CloseFriend(x.ui);Pump(x.view);Check(!blur.enabled);x.view.Dispose();});
  Test("native wrapper sorting order and backdrop restore across repeated sessions",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;for(int i=0;i<15;i++){x.ui.gameObject.SetActive(true);OpenFriend(x);Pump(x.view);Check(!blur.enabled&&x.renderer.sortingOrder==22);CloseFriend(x.ui);Pump(x.view);Check(blur.enabled&&x.renderer.sortingOrder==2);}x.view.Dispose();});
  Test("native direct lookup is independent of CLR proxy allocation order",()=>{var x=FriendFixture();Obj.NativeRendererWrappers=true;var ignored=x.ui.GetComponentsInChildren<Renderer>(true);var blur=NativeBlur(x.ui);var second=x.ui.GetComponentsInChildren<Renderer>(true);OpenFriend(x);Check(!blur.enabled);x.view.Dispose();});
  Test("before-cull catches known backdrop reenabled after LateUpdate",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);OpenFriend(x);Pump(x.view,3);var pos=x.ui.transform.position;blur.enabled=true;Call("BeforeCamera",Camera.main);Check(!blur.enabled);Near(x.ui.transform.position.x,pos.x);Near(x.ui.transform.position.y,pos.y);x.view.Dispose();});
  Test("pre-render guard runs even after diagnostics reach their session cap",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);for(int i=0;i<4;i++){x.ui.gameObject.SetActive(true);OpenFriend(x);Pump(x.view,3);blur.enabled=true;Call("BeforeCamera",Camera.main);Check(!blur.enabled);CloseFriend(x.ui,true);}x.view.Dispose();});
  Test("other camera cannot trigger native backdrop suppression",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);OpenFriend(x);blur.enabled=true;var other=new GameObject("OtherCamera").AddComponent<Camera>();Call("BeforeCamera",other);Check(blur.enabled);x.view.Dispose();});
  Test("no known Blur does not trigger speculative hiding of a full-screen renderer",()=>{var x=FriendFixture();var panel=new GameObject("UnknownScreenShade").AddComponent<SpriteRenderer>();panel.transform.SetParent(x.ui.transform,false);OpenFriend(x);RenderFriendFrame();Check(panel.enabled);x.view.Dispose();});
  Test("before and after traces identify typed native sprite vs CLR base wrapper",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;OpenFriend(x);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("node=Blur")&&s.Contains("clrSprite=False")&&s.Contains("nativeSprite=True")));Check(AuditLog.Any(s=>s.Contains("PHASE before_open")&&s.Contains("blurEnabled=True")));Check(AuditLog.Any(s=>s.Contains("PHASE shell_applied")&&s.Contains("blurEnabled=False")));x.view.Dispose();});
  Test("native material and tint changes are recorded without changing their values",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);var material=new Material(new Shader{name="Custom/Blur"});material.Colors["_Color"]=new(.2f,.3f,.4f,.5f);material.Floats["_Saturation"]=.7f;blur.sharedMaterial=material;OpenFriend(x);Check(AuditLog.Any(s=>s.Contains("shader=Custom/Blur")&&s.Contains("_Saturation=0.7")));Near(material.Floats["_Saturation"],.7);Near(blur.color.r,.3);x.view.Dispose();});
  Test("native menu screenTint activation is traced without guessing it should be disabled",()=>{var x=FriendFixture();OpenFriend(x);x.menu.screenTint.enabled=true;Call("BeforeCamera",Camera.main);Check(x.menu.screenTint.enabled&&AuditLog.Any(s=>s.Contains("key=R"+x.menu.screenTint.GetInstanceID())&&s.Contains("enabled=True")));x.view.Dispose();});
  Test("Canvas Image and CanvasGroup state are observed without mutation",()=>{var x=FriendFixture();var group=new GameObject("CanvasGroup").AddComponent<CanvasGroup>();group.alpha=.4f;group.blocksRaycasts=false;var canvas=group.gameObject.AddComponent<Canvas>();canvas.sortingOrder=123;var image=group.gameObject.AddComponent<Image>();image.color=new(.1f,.2f,.3f,.6f);image.canvasRenderer=group.gameObject.AddComponent<CanvasRenderer>();OpenFriend(x);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("key=G")&&s.Contains("alpha=0.4")));Check(AuditLog.Any(s=>s.Contains("key=C")&&s.Contains("order=123")));Check(AuditLog.Any(s=>s.Contains("key=I")&&s.Contains("color=0.1,0.2,0.3,0.6")));Near(group.alpha,.4);Check(!group.blocksRaycasts&&image.enabled&&canvas.sortingOrder==123);x.view.Dispose();});
  Test("main camera colour changes are visible in delta logs without modifying the camera",()=>{var x=FriendFixture();OpenFriend(x);Camera.main.backgroundColor=new(.2f,.4f,.6f,.8f);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("key=camera")&&s.Contains("background=0.2,0.4,0.6,0.8")));Near(Camera.main.backgroundColor.a,.8);x.view.Dispose();});
  Test("post-render trace distinguishes actual late reenable from suppression success",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);OpenFriend(x);Call("BeforeCamera",Camera.main);blur.enabled=true;Call("AfterFriendsCamera",Camera.main);Check(blur.enabled&&AuditLog.Any(s=>s.Contains("PHASE late_reenabled")&&s.Contains("blurEnabled=True")));x.view.Dispose();});
  Test("logs include no arbitrary object names text material names or unknown shader names",()=>{var x=FriendFixture();x.row.gameObject.name="PRIVATE_DUMMY_ACCOUNT_TOKEN";var mat=new Material(new Shader{name="PRIVATE_DUMMY_SHADER_TOKEN"}){name="PRIVATE_DUMMY_MATERIAL_TOKEN"};x.renderer.sharedMaterial=mat;var text=x.row.gameObject.AddComponent<TMPro.TextMeshPro>();text.text="PRIVATE_DUMMY_EMAIL_TOKEN";OpenFriend(x);RenderFriendFrame();Check(!string.Join("\n",AuditLog).Contains("PRIVATE_DUMMY"));x.view.Dispose();});
  Test("audit reports missing direct backdrop without claiming suppression",()=>{var x=FriendFixture();OpenFriend(x);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("typedBlur=0")&&s.Contains("blurEnabled=False")));Check(x.view.Visible);x.view.Dispose();});
  Test("audit occurs on events rather than every menu tick",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view);RenderFriendFrame();for(int warm=0;warm<60;warm++){Pump(x.view,1);RenderFriendFrame();}int count=AuditLog.Count();for(int i=0;i<100;i++){Pump(x.view,1);RenderFriendFrame();}Check(AuditLog.Count()==count&&count<=129);x.view.Dispose();});
  Test("only first two openings in a menu lifetime emit diagnostics",()=>{var x=FriendFixture();for(int i=0;i<5;i++){x.ui.gameObject.SetActive(true);OpenFriend(x);Pump(x.view);RenderFriendFrame();CloseFriend(x.ui,true);}Check(AuditLog.Count(s=>s.StartsWith("FRIENDS_RENDER_AUDIT_V3"))==2&&AuditLog.Count()<=258);x.view.Dispose();});
  Test("diagnostic logging exceptions do not disable the menu or block native close",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Logger.FailAudit=true;OpenFriend(x);RenderFriendFrame();Check(x.view.Visible&&!blur.enabled);CloseFriend(x.ui,true);Check(!x.view.FriendsBlocking&&x.ui.CloseCalls==1);Logger.FailAudit=false;x.view.Dispose();});
  Test("diagnostic bounds failure is contained without hiding unrelated renderers",()=>{var x=FriendFixture();var r=new GameObject("DummyRenderer").AddComponent<ThrowingAuditRenderer>();r.transform.SetParent(x.ui.transform,false);OpenFriend(x);Check(x.view.Visible&&r.enabled&&AuditLog.Any(s=>s.StartsWith("AUDIT_READ_FAILED")));Check(!string.Join("\n",AuditLog).Contains("DUMMY_EXCEPTION_PAYLOAD"));x.view.Dispose();});
  Test("game scene never enables a backdrop guard or emits a new before-open trace",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);GameScene();int count=AuditLog.Count();Call("FriendsOpening");Call("BeforeCamera",Camera.main);Call("AfterFriendsCamera",Camera.main);Check(blur.enabled&&AuditLog.Count()==count);x.view.Dispose();});
  Test("explicit game scene teardown restores known native state and does not force native close",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;OpenFriend(x);GameScene();Call("Tick",x.menu);Check(blur.enabled&&x.ui.CloseCalls==0);});
  Test("native friend input remains available under base wrapper rendering",()=>{var x=FriendFixture();NativeBlur(x.ui);Obj.NativeRendererWrappers=true;OpenFriend(x);RenderFriendFrame();Check((bool)Call("StartupClick",x.row)&&x.row.Colliders[0].enabled&&!(bool)Call("StartupClick",Proxy("Play")));x.view.Dispose();});
  Test("post-render diagnostics never advance the slide timeline",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,3);float pos=x.ui.transform.position.x;for(int i=0;i<8;i++)RenderFriendFrame();Near(x.ui.transform.position.x,pos);x.view.Dispose();});
  Test("typed backdrop restoration survives force close during opening",()=>{var x=FriendFixture();var blur=NativeBlur(x.ui);Obj.NativeRendererWrappers=true;OpenFriend(x);Pump(x.view,3);CloseFriend(x.ui,true);Check(blur.enabled&&!x.view.FriendsBlocking&&x.renderer.sortingOrder==2);x.view.Dispose();});
  Test("diagnostics use invariant decimal formatting",()=>{var prior=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=new("fr-FR");var x=FriendFixture();OpenFriend(x);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("size=3")&&s.Contains("aspect=1.778")));x.view.Dispose();}finally{CultureInfo.CurrentCulture=prior;}});
  Test("stable sample captures delayed canvas changes after native opening",()=>{var x=FriendFixture();var group=new GameObject("Group").AddComponent<CanvasGroup>();OpenFriend(x);for(int i=0;i<60;i++){if(i==30)group.alpha=.25f;Pump(x.view,1);RenderFriendFrame();}Check(AuditLog.Any(s=>s.Contains("PHASE stable_render"))&&AuditLog.Any(s=>s.Contains("phase=stable_render")&&s.Contains("alpha=0.25")));x.view.Dispose();});
  Test("additional cameras are recorded read-only to distinguish a second render pass",()=>{var x=FriendFixture();var other=new GameObject("OtherCamera").AddComponent<Camera>();other.depth=10;other.cullingMask=123;OpenFriend(x);RenderFriendFrame();Check(AuditLog.Any(s=>s.Contains("key=K"+other.GetInstanceID())&&s.Contains("depth=10")&&s.Contains("mask=123")));Check(other.enabled&&other.cullingMask==123);x.view.Dispose();});

 }
 class ThrowingAuditRenderer:Renderer {public override Bounds bounds {get=>throw new Exception("DUMMY_EXCEPTION_PAYLOAD");set{}}}
}
